function solve(matrix) {
  const R = matrix.length;
  if (R === 0) return [];
  const C = matrix[0].length;
  if (C === 0) return [];
  const out = [];
  for (let r = 0; r < C; r++) out.push(new Array(R).fill(0));
  for (let r = 0; r < C; r++) {
    for (let c = 0; c < R; c++) {
      for (let i = 0; i < R; i++) {
        for (let j = 0; j < C; j++) {
          if (i === R - 1 - c && j === r) out[r][c] = matrix[i][j];
        }
      }
    }
  }
  return out;
}

function solve(matrix) {
  const R = matrix.length;
  if (R === 0) return [];
  const C = matrix[0].length;
  if (C === 0) return [];
  const out = [];
  for (let r = 0; r < C; r++) out.push(new Array(R).fill(0));
  for (let i = 0; i < R; i++) {
    for (let j = 0; j < C; j++) {
      out[j][R - 1 - i] = matrix[i][j];
    }
  }
  return out;
}
